     1	// A word is a run of letters or digits (any script), optionally joined to the
     2	// next run by a single apostrophe (straight or typographic) or hyphen. The
     3	// joiners are only part of a word when letters or digits sit on both sides, so
     4	// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
     5	// em dashes, periods and underscores, separates words.
     6	const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;
     7	
     8	function assertText(fn, value) {
     9	  if (typeof value !== 'string') {
    10	    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
    11	  }
    12	}
    13	
    14	// Private: the single definition of "word" shared by every statistic below.
    15	function tokenize(text) {
    16	  return text.match(WORD_PATTERN) ?? [];
    17	}
    18	
    19	/**
    20	 * Count the words in a piece of text.
    21	 *
    22	 * @param {string} text
    23	 * @returns {number}
    24	 */
    25	function wordCount(text) {
    26	  assertText('wordCount', text);
    27	  return tokenize(text).length;
    28	}
    29	
    30	// Words whose trailing period does not end a sentence. Compared lower-case and
    31	// without any opening bracket or quote. "U.S.A." style initialisms are not
    32	// listed: they usually do end a sentence when they come last, and guessing
    33	// otherwise would trade one error for another.
    34	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
    35	
    36	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
    37	// only where whitespace or the end of the text follows. Requiring that keeps
    38	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
    39	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
    40	
    41	function endsWithAbbreviation(before) {
    42	  const last = before.match(/(\S+)$/);
    43	  if (last === null) {
    44	    return false;
    45	  }
    46	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
    47	  return ABBREVIATIONS.has(word);
    48	}
    49	
    50	/**
    51	 * Count the sentences in a piece of text.
    52	 *
    53	 * A sentence is a stretch of text containing at least one word and ending at a
    54	 * terminator run, or at the end of the text. A lone period after a known
    55	 * abbreviation does not end a sentence.
    56	 *
    57	 * @param {string} text
    58	 * @returns {number}
    59	 */
    60	function sentenceCount(text) {
    61	  assertText('sentenceCount', text);
    62	  let count = 0;
    63	  let start = 0;
    64	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
    65	    const before = text.slice(start, match.index);
    66	    if (match[1] === '.' && endsWithAbbreviation(before)) {
    67	      continue;
    68	    }
    69	    if (tokenize(before).length > 0) {
    70	      count += 1;
    71	    }
    72	    start = match.index + match[0].length;
    73	  }
    74	  if (tokenize(text.slice(start)).length > 0) {
    75	    count += 1;
    76	  }
    77	  return count;
    78	}
    79	
    80	// Function words that would otherwise crowd every ranking. The list is
    81	// deliberately short and fixed: callers who need a different list can filter
    82	// the full ranking (pass a large n) themselves.
    83	const STOP_WORDS = new Set([
    84	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
    85	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
    86	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
    87	  'will', 'with',
    88	]);
    89	
    90	/**
    91	 * List the most frequent words in a piece of text.
    92	 *
    93	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
    94	 * and stop words are skipped. Entries are ordered by count (highest first),
    95	 * then alphabetically, so the result is deterministic.
    96	 *
    97	 * @param {string} text
    98	 * @param {number} n How many entries to return; a non-negative integer.
    99	 * @returns {Array<{word: string, count: number}>}
   100	 */
   101	function topWords(text, n) {
   102	  assertText('topWords', text);
   103	  if (!Number.isInteger(n) || n < 0) {
   104	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
   105	  }
   106	  const counts = new Map();
   107	  for (const token of tokenize(text)) {
   108	    const word = token.toLowerCase().replace(/’/g, "'");
   109	    if (STOP_WORDS.has(word)) {
   110	      continue;
   111	    }
   112	    counts.set(word, (counts.get(word) ?? 0) + 1);
   113	  }
   114	  return [...counts]
   115	    .map(([word, count]) => ({ word, count }))
   116	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
   117	    .slice(0, n);
   118	}
   119	
   120	const DEFAULT_WORDS_PER_MINUTE = 200;
   121	
   122	/**
   123	 * Estimate how many whole minutes a text takes to read.
   124	 *
   125	 * The estimate is the word count divided by the reading rate, rounded up, so
   126	 * any text with at least one word takes at least a minute and the empty text
   127	 * takes none.
   128	 *
   129	 * @param {string} text
   130	 * @param {number} [wpm=200] Reading rate in words per minute; a positive, finite number.
   131	 * @returns {number} Whole minutes.
   132	 */
   133	function readingTimeMinutes(text, wpm = DEFAULT_WORDS_PER_MINUTE) {
   134	  assertText('readingTimeMinutes', text);
   135	  if (typeof wpm !== 'number' || !Number.isFinite(wpm) || wpm <= 0) {
   136	    throw new RangeError(`readingTimeMinutes: wpm must be a positive finite number, received ${String(wpm)}`);
   137	  }
   138	  return Math.ceil(wordCount(text) / wpm);
   139	}
   140	
   141	module.exports = { wordCount, sentenceCount, topWords, readingTimeMinutes };
